contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // Contract is fresh/uninitialized, so we can set MinSum to 0 so that
        // any positive balance satisfies the Collect threshold.
        c.SetMinSum(0);

        // Fund the caller's recorded balance in c.
        c.Deposit{value: amount}();

        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;
        require(balBefore >= amount);

        // Collect must pass the balance checks (bal >= MinSum, bal >= amount),
        // but the Ether transfer to this contract always fails (see receive),
        // so Collect must revert and leave all balances unchanged.
        bool reverted;
        try c.Collect(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.balances(address(this)) == balBefore && address(c).balance == contractBalBefore);
    }

    receive() external payable {
        // Always reject incoming Ether so that Collect's transfer fails.
        revert("reject");
    }
}

contract InvMutTest {
    C c;
    bool rejectEther;
    constructor(C _c) { c = _c; }
    function run(uint depositAmount, uint collectAmount, uint minSum) public payable {
        require(address(this).balance >= depositAmount);
        c.SetMinSum(minSum);
        c.SetLogFile(address(this));
        c.Initialized();
        c.Deposit{value: depositAmount}();
        require(c.balances(address(this)) >= minSum);
        require(c.balances(address(this)) >= collectAmount);
        require(collectAmount <= depositAmount);
        rejectEther = true;
        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }
        rejectEther = false;
        assert(reverted && c.balances(address(this)) == depositAmount);
    }
    receive() external payable {
        if (rejectEther) { revert(); }
    }
}
